def zero_pad_id(n, width):
    s = str(n)
    if len(s) >= width:
        return s
    if n < 0:
        digits = str(-n)
        return '-' + digits.zfill(width)
    return s.zfill(width)

def format_id_with_check_digit(n, width):
    padded = str(n).zfill(width)
    digit_sum = sum(int(c) for c in padded if c.isdigit())
    check = digit_sum % 10
    return padded + str(check)

def format_id_grouped(n, width, group):
    padded = str(n).zfill(width)
    chunks = [padded[i:i + group] for i in range(0, len(padded), group)]
    return '-'.join(chunks)

def parse_and_reformat_id(id_str, new_width):
    stripped = id_str.lstrip('0')
    if stripped == '':
        stripped = '0'
    if len(stripped) >= new_width:
        return stripped
    return stripped.zfill(new_width)

def sentence_case_multi(text):
    fragments = text.split('. ')
    result = []
    for frag in fragments:
        lower = frag.lower()
        idx = None
        for i, c in enumerate(lower):
            if c.isalpha():
                idx = i
                break
        if idx is None:
            result.append(lower)
        else:
            result.append(lower[:idx] + lower[idx].upper() + lower[idx + 1:])
    return '. '.join(result)

def capitalize_first_word_each_line(text):
    lines = text.split('\n')
    result = []
    for line in lines:
        if line == '':
            result.append('')
            continue
        lower = line.lower()
        idx = None
        for i, c in enumerate(lower):
            if c.isalpha():
                idx = i
                break
        if idx is None:
            result.append(lower)
        else:
            result.append(lower[:idx] + lower[idx].upper() + lower[idx + 1:])
    return '\n'.join(result)

def sentence_case_preserve_acronyms(s, acronyms):
    lower = s.lower()
    idx = None
    for i, c in enumerate(lower):
        if c.isalpha():
            idx = i
            break
    if idx is None:
        sentence_cased = lower
    else:
        sentence_cased = lower[:idx] + lower[idx].upper() + lower[idx + 1:]
    words = sentence_cased.split(' ')
    acronym_map = {a.lower(): a for a in acronyms}
    result_words = []
    for w in words:
        if w.lower() in acronym_map:
            result_words.append(acronym_map[w.lower()])
        else:
            result_words.append(w)
    return ' '.join(result_words)

import re


def fix_sentence_spacing(s):
    collapsed = re.sub(r'\s+', ' ', s).strip()
    lower = collapsed.lower()
    idx = None
    for i, c in enumerate(lower):
        if c.isalpha():
            idx = i
            break
    if idx is None:
        return lower
    return lower[:idx] + lower[idx].upper() + lower[idx + 1:]

def capitalize_after_colon(s):
    lower = s.lower()
    chars = list(lower)
    for i, c in enumerate(chars):
        if c.isalpha():
            chars[i] = c.upper()
            break
    start = 0
    while True:
        pos = lower.find(': ', start)
        if pos == -1:
            break
        after = pos + 2
        for i in range(after, len(chars)):
            if chars[i].isalpha():
                chars[i] = chars[i].upper()
                break
        start = pos + 2
    return ''.join(chars)

def sentence_case_keep_i(s):
    lower = s.lower()
    words = lower.split(' ')
    words = ['I' if w == 'i' else w for w in words]
    joined = ' '.join(words)
    idx = None
    for i, c in enumerate(joined):
        if c.isalpha():
            idx = i
            break
    if idx is None:
        return joined
    return joined[:idx] + joined[idx].upper() + joined[idx + 1:]

def toggle_sentence_case(s):
    first_alpha_idx = None
    for i, c in enumerate(s):
        if c.isalpha():
            first_alpha_idx = i
            break
    if first_alpha_idx is None:
        return s.lower()
    result = []
    seen_first = False
    for c in s:
        if c.isalpha():
            if not seen_first:
                result.append(c.lower())
                seen_first = True
            else:
                result.append(c.upper())
        else:
            result.append(c)
    return ''.join(result)

def sanitize_filename_basic(name):
    allowed = set('-_.')
    result = []
    for c in name:
        if c.isalnum() or c in allowed:
            result.append(c)
        else:
            result.append('_')
    return ''.join(result)

def sanitize_filename_spaces(name):
    replaced = name.replace(' ', '_')
    allowed = set('-_.')
    return ''.join(c for c in replaced if c.isalnum() or c in allowed)

def sanitize_filename_lower(name):
    lowered = name.lower()
    replaced = lowered.replace(' ', '-')
    result = []
    for c in replaced:
        if c.isalpha() or c.isdigit() or c in '-.':
            result.append(c)
    return ''.join(result)

import re


def collapse_underscores(name):
    collapsed = re.sub(r'_{2,}', '_', name)
    return collapsed.strip('_')
